import pathlib,json,subprocess,hashlib,zipfile,tarfile,shutil
repo=pathlib.Path.cwd();base=pathlib.Path(__file__).resolve().parent;info=json.loads((base/'build.json').read_text());rev=info['revision'];assert not (base/'node-release.json').exists();assert rev==subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()
out=repo/'evidence/2026-10-23/runpod-optimization/pipeline';tests=json.loads((out/'tool-validation/java-tests.json').read_text());assert tests['exitCode']==0 and tests['failures']==0 and tests['skipped']==0
