def entries(p):
 with zipfile.ZipFile(p) as z:return {n:hashlib.sha256(z.read(n)).hexdigest() for n in z.namelist() if not n.endswith('/')}
assert old.is_dir() and new.is_dir() and list(old.glob('*.jar')) and {p.name for p in old.glob('*.jar')}=={p.name for p in new.glob('*.jar')},'JAR filename set changed'
unchanged={};files={};diff=[]
for p in sorted(new.glob('*.jar')):
 a,b=entries(old/p.name),entries(p)
 if p.name.startswith('cluster-'):
  exclude=lambda n:n.startswith(('io/vectormatch/cluster/ClusterClient','io/vectormatch/cluster/RemoteCapacityExperiment','io/vectormatch/cluster/MultiplexedLoadTransports'))
  assert {n:h for n,h in a.items() if not exclude(n)}=={n:h for n,h in b.items() if not exclude(n)},'unexpected class change'
  unchanged={n:h for n,h in b.items() if not exclude(n)};diff=[n for n in sorted(set(a)|set(b)) if a.get(n)!=b.get(n)]
 else:assert a==b,'dependency changed'
 shutil.copyfile(p,lib/p.name)
for name in ['deploy/remote_service.py','deploy/test_remote_service.py','scripts/capacity-telemetry.py','scripts/tests/test_capacity_telemetry.py']:
 t=stage/name;t.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(build/name,t)
for p in stage.rglob('*'):
 if p.is_file():files[str(p.relative_to(stage))]=hashlib.sha256(p.read_bytes()).hexdigest()
manifest={'revision':rev,'role':'capacity-node-and-load-physical-session-arrangement-control','comparedAgainstNodeRevision':prior['revision'],'changedClusterEntries':diff,'unchangedClusterEntriesSha256':unchanged,'files':files,'sourceArchiveSha256':info['sourceArchiveSha256'],'scope':'One source-pinned common node/load artifact for direct128sessions vs multiplexed1session at identical128logical in-flight/FIFO8192. Compare toab6: only ClusterClient,RemoteCapacityExperiment,MultiplexedLoadTransports class families may differ. NodeMain,matching core,ClusterCapacity and dependencies byte-identical, exact JAR filename sets required. NAK1000ns/ratio100 both node+load; no older identity overwrite.'};(stage/'DEPLOYMENT.json').write_text(json.dumps(manifest,indent=2)+'\n')
archive=base/('node-'+rev+'.tar.gz')
with tarfile.open(archive,'w:gz') as t:
 for p in sorted(stage.iterdir()):t.add(p,arcname=p.name)
release={'revision':rev,'root':'/opt/vectormatch/optimization-node-releases/'+rev,'archive':str(archive),'bundleSha256':hashlib.sha256(archive.read_bytes()).hexdigest(),'archiveBytes':archive.stat().st_size};(base/'node-release.json').write_text(json.dumps(release,indent=2)+'\n');(out/'node-deployment-manifest.json').open('x').write(json.dumps(manifest,indent=2)+'\n');(out/'node-release.json').open('x').write(json.dumps(release,indent=2)+'\n');print(json.dumps(release));print('changed entries',diff)
